INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S4-Q21$batch08$, 156, 4, 21, $batch08$Principle-Conform$batch08$, $batch08$Company policy: Eligible employees will be granted up to six weeks of paid parental leave following the birth or adoption of a child. To be eligible, an employee must apply for the benefit at least three months prior to the beginning of the leave period and must have at least one year of full- time employment with the company at the time of application.$batch08$, $batch08$Which one of the following judgments most closely conforms to the company policy?$batch08$, $batch08$E$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Mac is a full-time employee who has been with the company for exactly one year. He just adopted a child, and he applied for parental leave three months ago, so Mac should be granted the leave.$batch08$, $batch08$Violates Rule$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Sara has worked full-time for the company for three years, and she applied for parental leave four months before the recent birth of her child. However, she should not be granted the leave because she took a leave of absence within the past year.$batch08$, $batch08$Violates Rule$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Hal, a second-year, full-time employee, applied for parental leave three months ago. He wishes to stay at home for only two weeks following the impending birth of his child, so the company should not grant him parental leave.$batch08$, $batch08$Violates Rule$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Dudley has worked part-time for the company for the past seven years. He applied for parental leave over three months before the birth of his child, so it should be granted to him.$batch08$, $batch08$Violates Rule$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Maria has worked full-time for the company for the past two years and applied for parental leave six months prior to her adoption of a child, so she should be granted parental leave.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Rule$batch08$, $batch08$An eligible employee gets up to six weeks of paid leave. Eligible means applying at least three months before the leave starts *and* having at least one year of full-time employment when applying.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Check each person against both requirements, measured at the time of application. Also watch for reasons to deny that the policy never gives.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Someone who meets both requirements and is granted leave.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Mac has one year now, but he applied three months ago, when he had only nine months. He wasn't eligible when he applied.$batch08$), ($batch08$B$batch08$, $batch08$Sara meets both requirements. A recent leave of absence isn't a reason the policy recognizes.$batch08$), ($batch08$C$batch08$, $batch08$The policy grants "up to" six weeks, so wanting only two is fine. Denying Hal on that basis doesn't follow the policy.$batch08$), ($batch08$D$batch08$, $batch08$Dudley has worked part-time. The policy requires full-time.$batch08$), ($batch08$E$batch08$, $batch08$Maria has two years full-time and applied six months ahead. She meets both requirements, so she gets the leave.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S4-Q21$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
